& {
    $ErrorActionPreference = 'Stop'
    $r = 'E:\Dev\uzdoom_src\doda-core'
    $tt = Join-Path $r 'generated\_tests_tmp'
    New-Item -ItemType Directory -Force -Path $tt | Out-Null
    $py = (Get-Command python -ErrorAction SilentlyContinue).Source
    if (-not $py) { $py = (Get-Command py -ErrorAction SilentlyContinue).Source }
    if (-not $py) { throw 'Python was not found.' }
    $env:TMP = $tt
    $env:TEMP = $tt
    $env:PYTHONDONTWRITEBYTECODE = '1'
    $code = @'
import ast, base64, hashlib, json, re, subprocess, sys, zlib
from datetime import datetime
from pathlib import Path
root = Path(sys.argv[1])
w = root / "tools/doda_content_workbench"
guards = {'tools\\doda_content_workbench\\doda_content_workbench.py': '90898DB301DE746FAF495C97ACF1D2675038E52F14433BF41EFD502F0056919B', 'tools\\doda_content_workbench\\doda_content_export.py': 'D145855F9C3078ABE9A8091E2C2826B18CE148A836D34931C5937EEF010F9C8B', 'tools\\doda_content_workbench\\doda_content_gui.py': 'D3410075ABD55236737981EBB9F3C94690D281FF0B82966C048279DD0C38805D', 'tools\\doda_content_workbench\\doda_network_editor.py': 'A72FF2DBF0F1F15EBA4D726392E8FA0686297D20C710076696EE19E1172C8E1D', 'tools\\doda_content_workbench\\doda_page_registry.py': '634E7055B737DA207017773714332724B958958F88CEAAA3285AAC79D5A68314', 'tools\\doda_content_workbench\\doda_navigation.py': '690BCEFBEB71DF4CA65CCCC490A15CE05A65B414E78447EE7B4D4B5B7AFC2F4D', 'tools\\doda_content_workbench\\doda_vehicle_rules.py': 'CD2AB122DACAE7DBCA418E6A4DE7702BE78955FFEBB4BBD3E3DFAE309BF12A83', 'data_authoring\\source\\vehicle_types.csv': 'C738588DFF81934E7B978ED0A9D8D8F5DC89BABBCA976AB295F3404EA499E673', 'tools\\doda_content_workbench\\doda_task_templates_editor.py': '3F8B0EAF592E2E8EC69FDF3516E8DF65A134ED86C546CD1E5085BC9DA6EEB752'}
content = json.loads(zlib.decompress(base64.b64decode('')))
def path(relative):
    return root.joinpath(*relative.split("\\"))
def digest(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()
for relative, expected in guards.items():
    p = path(relative)
    if not p.is_file() or digest(p).upper() != expected.upper():
        raise SystemExit("STOP: Checkpoint differs: " + str(p))
for relative, text in content.items():
    p = path(relative)
    if relative not in guards and p.exists():
        raise SystemExit("STOP: New target exists: " + str(p))
    if p.suffix == ".py":
        compile(text, str(p), "exec")
        ast.parse(text)
print("CHECKPOINT HASHES AND CANDIDATE SYNTAX: PASS", flush=True)
def suite(expected):
    run = subprocess.run([sys.executable, "-m", "unittest", "discover", "-s", "tests"], cwd=w,
                         capture_output=True, text=True, encoding="utf-8", errors="replace")
    output = run.stdout + "\n" + run.stderr
    match = re.search(r"Ran (\d+) tests", output)
    print(output, flush=True)
    if run.returncode or not match or int(match.group(1)) != expected:
        raise RuntimeError("Expected " + str(expected) + " passing tests.")
suite(614)
src = root / "data_authoring/source"
source_before = {p: digest(p) for p in src.glob("*.csv")}
originals = {relative: path(relative).read_bytes() if path(relative).exists() else None for relative in content}
backup = w / "backups" / ("v110_vehicle_integration_" + datetime.now().strftime("%Y%m%d_%H%M%S_%f"))
backup.mkdir(parents=True, exist_ok=False)
for relative, original in originals.items():
    if original is not None:
        dest = backup.joinpath(*relative.split("\\"))
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(original)
(backup / "manifest.json").write_text(json.dumps({r: "NEW" if b is None else hashlib.sha256(b).hexdigest() for r,b in originals.items()}, indent=2), encoding="utf-8")
print("Backup folder:", backup, flush=True)
written = []
try:
    for relative, expected in guards.items():
        if digest(path(relative)).upper() != expected.upper():
            raise RuntimeError("Checkpoint changed during preparation: " + relative)
    for relative, value in content.items():
        p = path(relative)
        if originals[relative] is None and p.exists():
            raise RuntimeError("New target appeared: " + relative)
        p.parent.mkdir(parents=True, exist_ok=True)
        written.append(relative)
        p.write_bytes(value.encode("utf-8"))
        print("WROTE SHA256", digest(p), relative, flush=True)
    suite(624)
    for p, before in source_before.items():
        if not p.exists() or digest(p) != before:
            raise RuntimeError("Source CSV changed: " + str(p))
    for relative, expected in guards.items():
        if relative not in content and digest(path(relative)).upper() != expected.upper():
            raise RuntimeError("Read-only guard changed: " + relative)
    print("RESULT: PASS. 624 tests; all existing source CSVs unchanged.", flush=True)
    print("Vehicle Types editor, candidate staging, validation and GUI Export All wired.", flush=True)
    print("No live export run; no inventory, allocation or runtime integration added.", flush=True)
except BaseException:
    for relative in reversed(written):
        p = path(relative)
        old = originals[relative]
        if old is None:
            p.unlink(missing_ok=True)
        else:
            p.write_bytes(old)
    print("PATCH ROLLED BACK. Existing application files restored; new files removed.", flush=True)
    raise

'@
    $pf = Join-Path $tt ('vehicle_integration_' + [guid]::NewGuid().ToString('N') + '.py')
    [System.IO.File]::WriteAllText($pf, ($code -replace "`r`n", "`n"), (New-Object System.Text.UTF8Encoding $false))
    $marker = '=== COPY FROM HERE ==='
    Write-Host $marker -ForegroundColor Yellow
    $savedPreference = $ErrorActionPreference
    try {
        $ErrorActionPreference = 'Continue'
        $output = @(& $py $pf $r 2>&1 | ForEach-Object { Write-Host "$_"; "$_" })
        $exitCode = $LASTEXITCODE
    }
    finally { $ErrorActionPreference = $savedPreference }
    $report = (@($marker) + $output + "Runner exit code: $exitCode") -join "`r`n"
    try {
        Set-Clipboard -Value $report
        Write-Host 'Report copied. Paste here with Ctrl+V.' -ForegroundColor Green
    }
    catch { Write-Warning 'Clipboard copy failed; output remains visible.' }
    if ($exitCode -ne 0) { throw 'Patch stopped. Paste the report; do not rerun earlier patches.' }
    Remove-Item -LiteralPath $pf
}
